def f(n):
    """Return a list of length `n` where the element at index `i`
    (with i starting from 0) is:
    - the factorial of i+1 if i+1 is even
    - the sum of numbers from 1 to i+1 otherwise
    """
    result = []
    for i in range(1, n + 1):
        if i % 2 == 0:
            fact = 1
            for j in range(1, i + 1):
                fact *= j
            result.append(fact)
        else:
            result.append(i * (i + 1) // 2)
    return result
